#include <vector>
#include <omp.h>

bool reduceLogicalXOR(std::vector<bool> const& x) {
    bool result = false;

    // OpenMP supports reduction on bool with the ^ operator in most compilers.
    // To be maximally portable, use an int reduction and convert at the end.
    int acc = 0;

    const int n = static_cast<int>(x.size());
#pragma omp parallel for reduction(^ : acc) schedule(static)
    for (int i = 0; i < n; ++i) {
        // vector<bool> returns a proxy; convert explicitly to int (0/1).
        acc ^= static_cast<int>(static_cast<bool>(x[static_cast<std::size_t>(i)]));
    }

    result = (acc != 0);
    return result;
}
